import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] inputLine = br.readLine().split(" ");
        int n = Integer.parseInt(inputLine[0]);
        int mod = Integer.parseInt(inputLine[1]);

        int[] memory = new int[n + 1];
        memory[0] = 0;
        memory[1] = 1;
        int totalSum = 1;

        for (int i = 2; i <= n; i++) {
            int sqrtLimit = (int) Math.sqrt(i) + 1;
            int currentValue = totalSum;

            for (int f = 2; f < sqrtLimit; f++) {
                int index = i / f;
                if (index <= n) {
                    currentValue = (currentValue + memory[index]) % mod;
                }
            }

            int boundary = i;
            for (int j = 1; j <= i / sqrtLimit; j++) {
                int nextBoundary = i / (j + 1);
                if (j <= n) {
                    currentValue = (currentValue + (boundary - nextBoundary) * memory[j]) % mod;
                }
                boundary = nextBoundary;
            }

            totalSum = (totalSum + currentValue) % mod;
            if (i <= n) {
                memory[i] = currentValue;
            }
        }
        System.out.println(memory[n]);
    }
}
